interface CacheEntry<V> {
    key: string;
    value: V;
    timestamp: number;
    ttl: number;
    size: number;
    accessCount: number;
    lastAccessed: number;
}

export interface LRUCacheOptions {
    max?: number;
    maxSize?: number;
    maxMemoryMB?: number;
    defaultTTL?: number;
    sizeCalculation?: <V>(value: V, key: string) => number;
}

export interface CacheStats {
    size: number;
    itemCount: number;
    hitCount: number;
    missCount: number;
    hitRate: number;
    memoryUsageMB: number;
    evictions: number;
}

export class LRUCache<K extends string = string, V = unknown> {
    private readonly _maxEntries: number;
    private readonly _maxMemoryMB: number;
    private readonly _defaultTTL: number;
    private readonly _sizeCalculation: <T>(value: T, key: string) => number;
    private readonly _map: Map<string, CacheEntry<V>>;
    private readonly _orderList: string[];
    private _memoryUsageMB = 0;
    private _hitCount = 0;
    private _missCount = 0;
    private _evictions = 0;

    public constructor(options?: LRUCacheOptions) {
        this._maxEntries = options?.max ?? 500;
        this._maxMemoryMB = options?.maxMemoryMB ?? 50;
        this._defaultTTL = options?.defaultTTL ?? 5 * 60 * 1000;
        this._sizeCalculation = options?.sizeCalculation ?? this.defaultSizeCalculation;
        this._map = new Map();
        this._orderList = [];
    }

    private defaultSizeCalculation<V>(value: V): number {
        try {
            const jsonString = JSON.stringify(value);
            return new Blob([jsonString]).size / (1024 * 1024);
        } catch {
            return 0.001;
        }
    }

    public get(key: K): V | undefined {
        const entry = this._map.get(key);

        if (!entry) {
            this._missCount++;
            return undefined;
        }

        const now = Date.now();
        if (entry.ttl > 0 && now - entry.timestamp > entry.ttl) {
            this.evict(key);
            this._missCount++;
            return undefined;
        }

        entry.accessCount++;
        entry.lastAccessed = now;

        this._hitCount++;
        this.promote(key);

        return entry.value;
    }

    public set(key: K, value: V, ttl?: number, size?: number): void {
        const existing = this._map.get(key);

        if (existing) {
            this._memoryUsageMB -= existing.size;
            this._map.delete(key);
            const idx = this._orderList.indexOf(key);
            if (idx !== -1) {
                this._orderList.splice(idx, 1);
            }
        }

        const entrySize = size ?? this._sizeCalculation(value, key);
        const now = Date.now();

        const entry: CacheEntry<V> = {
            key,
            value,
            timestamp: now,
            ttl: ttl ?? this._defaultTTL,
            size: entrySize,
            accessCount: 0,
            lastAccessed: now,
        };

        this._memoryUsageMB += entrySize;

        while (this._map.size >= this._maxEntries || this._memoryUsageMB > this._maxMemoryMB) {
            this.evictOldest();
        }

        this._map.set(key, entry);
        this._orderList.push(key);
    }

    public has(key: K): boolean {
        const entry = this._map.get(key);
        if (!entry) {
            return false;
        }

        if (entry.ttl > 0 && Date.now() - entry.timestamp > entry.ttl) {
            this.evict(key);
            return false;
        }

        return true;
    }

    public delete(key: K): boolean {
        const entry = this._map.get(key);
        if (entry) {
            this._memoryUsageMB -= entry.size;
            this._map.delete(key);
            const idx = this._orderList.indexOf(key);
            if (idx !== -1) {
                this._orderList.splice(idx, 1);
            }
            return true;
        }
        return false;
    }

    public clear(): void {
        this._map.clear();
        this._orderList.length = 0;
        this._memoryUsageMB = 0;
    }

    public getStats(): CacheStats {
        const totalRequests = this._hitCount + this._missCount;
        return {
            size: this._map.size,
            itemCount: this._map.size,
            hitCount: this._hitCount,
            missCount: this._missCount,
            hitRate: totalRequests > 0 ? (this._hitCount / totalRequests) * 100 : 0,
            memoryUsageMB: this._memoryUsageMB,
            evictions: this._evictions,
        };
    }

    public keys(): IterableIterator<K> {
        return this._map.keys() as IterableIterator<K>;
    }

    public values(): IterableIterator<V> {
        return this._map.values() as IterableIterator<V>;
    }

    public entries(): IterableIterator<[K, V]> {
        return this._map.entries() as IterableIterator<[K, V]>;
    }

    public get size(): number {
        return this._map.size;
    }

    public get memoryUsage(): number {
        return this._memoryUsageMB;
    }

    public peek(key: K): V | undefined {
        return this._map.get(key)?.value;
    }

    public invalidateIf(predicate: (key: K, value: V) => boolean): number {
        const keysToDelete: K[] = [];

        for (const [key, entry] of this._map.entries()) {
            if (predicate(key as K, entry.value)) {
                keysToDelete.push(key as K);
            }
        }

        for (const key of keysToDelete) {
            this.delete(key);
        }

        return keysToDelete.length;
    }

    public invalidateByPrefix(prefix: string): number {
        return this.invalidateIf((key) => (key as string).startsWith(prefix));
    }

    public invalidateByTTL(maxAge: number): number {
        const now = Date.now();
        return this.invalidateIf((_, entry) => {
            const cacheEntry = entry as CacheEntry<V>;
            return now - cacheEntry.timestamp > maxAge;
        });
    }

    private promote(key: K): void {
        const idx = this._orderList.indexOf(key);
        if (idx !== -1 && idx < this._orderList.length - 1) {
            this._orderList.splice(idx, 1);
            this._orderList.push(key);
        }
    }

    private evict(key: K): void {
        const entry = this._map.get(key);
        if (entry) {
            this._memoryUsageMB -= entry.size;
            this._map.delete(key);
            const idx = this._orderList.indexOf(key);
            if (idx !== -1) {
                this._orderList.splice(idx, 1);
            }
            this._evictions++;
        }
    }

    private evictOldest(): void {
        if (this._orderList.length === 0) {
            return;
        }

        const oldestKey = this._orderList[0];
        this.evict(oldestKey as K);
    }

    public dump(): Map<string, { value: V; timestamp: number; ttl: number }> {
        const dump = new Map<string, { value: V; timestamp: number; ttl: number }>();

        for (const [key, entry] of this._map.entries()) {
            dump.set(key, {
                value: entry.value,
                timestamp: entry.timestamp,
                ttl: entry.ttl,
            });
        }

        return dump;
    }

    public load(data: Map<string, { value: V; timestamp: number; ttl: number }>): void {
        this.clear();

        for (const [key, entry] of data.entries()) {
            this.set(key as K, entry.value, entry.ttl);
        }
    }
}

export function createMemoryCache<K extends string = string, V = unknown>(options?: LRUCacheOptions): LRUCache<K, V> {
    return new LRUCache(options);
}
